)

style_number4 <- openxlsx::createStyle(numFmt = "0.0000")
style_number1 <- openxlsx::createStyle(numFmt = "0.00")

comparison_sheet <- "Estimator_Comparison"
openxlsx::mergeCells(workbook, comparison_sheet, cols = 1:5, rows = 1)
openxlsx::writeData(
  workbook,
  comparison_sheet,
  "Simulation performance across four nuisance-model specification scenarios",
  startCol = 1,
  startRow = 1,
  colNames = FALSE
)
openxlsx::addStyle(
  workbook,
  comparison_sheet,
  style_title,
  rows = 1,
  cols = 1:5,
  gridExpand = TRUE
)
openxlsx::setRowHeights(workbook, comparison_sheet, rows = 1, heights = 30)

actual_replicates <- scenario_summary[, unique(n_replicates)]
replicate_text <- if (length(actual_replicates) == 1L) {
  paste0(
    "Based on ",
    actual_replicates,
    " Monte Carlo replicates per scenario. Scenario-specific results are ",
    "shown for all four scenarios; overall summaries use the three scenarios ",
    "in which at least one nuisance model was correctly specified."
  )
} else {
  paste0(
    "The number of Monte Carlo replicates varied across scenarios. ",
    "Scenario-specific results are shown for all four scenarios; overall ",
    "summaries use the three scenarios in which at least one nuisance model ",
    "was correctly specified."
  )
}

openxlsx::mergeCells(workbook, comparison_sheet, cols = 1:5, rows = 2)
openxlsx::writeData(
  workbook,
