)

openxlsx::setColWidths(
  workbook,
  comparison_sheet,
  cols = 1,
  widths = 52
)
openxlsx::setColWidths(
  workbook,
  comparison_sheet,
  cols = 2:5,
  widths = 22
)
openxlsx::setRowHeights(
  workbook,
  comparison_sheet,
  rows = 4,
  heights = 52
)
openxlsx::setRowHeights(
  workbook,
  comparison_sheet,
  rows = 5:(4 + n_compact_rows),
  heights = 32
)
openxlsx::freezePane(
  workbook,
  comparison_sheet,
  firstActiveRow = 5,
  firstActiveCol = 2
)

note_start_row <- 4 + n_compact_rows + 2
notes <- c(
  "Notes:",
  paste0(
    "The first four rows report scenario-specific absolute empirical bias for ",
    "the additional event-history log mortality rate-ratio coefficient."
  ),
  paste0(
    "Overall coefficient-bias, worst-case-bias, attributable-fraction-bias, ",
    "and coverage summaries are calculated across the three scenarios in ",
    "which at least one nuisance model was correctly specified."
  ),
  paste0(
    "The both-misspecified scenario is shown to evaluate the boundary of the ",
    "double-robustness property but is not pooled into the primary overall ",
    "summaries."
  ),
  paste0(
    "Arrows indicate the preferred direction: lower bias is better, higher ",
    "convergence is better, and coverage is best when close to 95%."
  ),
  "AF, attributable fraction; AIPW, augmented inverse probability weighting; EE, estimating equation."
)

for (note_index in seq_along(notes)) {
  row_value <- note_start_row + note_index - 1L
  openxlsx::mergeCells(
    workbook,
    comparison_sheet,
    cols = 1:5,
    rows = row_value
  )
  openxlsx::writeData(
    workbook,
    comparison_sheet,
    notes[note_index],
    startCol = 1,
    startRow = row_value,
    colNames = FALSE
  )
}

